import randomimport hangman_artimport hangman_words# TODO-3: - Import the logo from hangman_art.py and print it at the start of the game.print(hangman_art.logo1)# TODO-1: - Update the word list to use the 'word_list' from hangman_words.pyword_list = hangman_words.word_listchosen_word = random.choice(word_list)print(chosen_word)display = []for _ in range(len(chosen_word)):    display.append("_")game_over = Falselives = 6while not game_over:    print(f"**********************You have {lives}/6 Lives**************************")    guess_letter = input("Please guess a letter: ").lower()    # TODO-4: - If the user has entered a letter they've already guessed, print the letter and let them know.    if guess_letter in display:        print(f"You've already guessed the letter {guess_letter}.")    for i in range(len(chosen_word)):        if chosen_word[i] == guess_letter:            display[i] = guess_letter    placeholder = ""    for letter in display:        placeholder += letter    print(placeholder)    if guess_letter not in chosen_word:        lives -= 1        # TODO-5: - If the letter is not in the chosen_word, print out the letter and let them know it's not in the word.        print(f"You guessed {guess_letter}, that's not in the word. You lose a life")        if lives == 0:            game_over = True            print(f"***********************IT WAS {chosen_word}! YOU LOSE**********************")    if "_" not in display:        game_over = True        print(hangman_art.logo2)    # TODO-2: - Import the stages from hangman_art.py and make this error go away.    print(hangman_art.stages[lives])